// *** IR Dump After LowerHLFIR (fir-lower-hlfir) ***
// With -fopenmp: DO CONCURRENT emits omp dialect
module @_QMdo_concurrent_scale {
  func.func @_QPdo_concurrent_scale(
      %arg0: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "a", fir.inout},
      %arg1: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "b", fir.in},
      %arg2: !fir.ref<f32>               {fir.bindc_name = "scale", fir.in},
      %arg3: !fir.ref<i32>               {fir.bindc_name = "n", fir.in}
  ) {
    %c1     = arith.constant 1 : index
    %n_val  = fir.load %arg3 : !fir.ref<i32>
    %n_idx  = fir.convert %n_val : (i32) -> index
    %scale  = fir.load %arg2 : !fir.ref<f32>
    %shape  = fir.shape %n_idx : (index) -> !fir.shape<1>
    %b_arr  = fir.array_load %arg1(%shape) : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> !fir.array<?xf32>
    %a_arr  = fir.array_load %arg0(%shape) : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> !fir.array<?xf32>

    // unordered attribute is the FIR encoding of DO CONCURRENT's
    // independence guarantee — enables loop transformations
    %result = fir.do_loop %iv = %c1 to %n_idx step %c1
                  unordered iter_args(%acc = %a_arr) -> (!fir.array<?xf32>) {
      %b_el  = fir.array_fetch %b_arr, %iv : (!fir.array<?xf32>, index) -> f32
      %prod  = arith.mulf %b_el, %scale fastmath<contract> : f32
      %a_upd = fir.array_update %acc, %prod, %iv : (!fir.array<?xf32>, f32, index) -> !fir.array<?xf32>
      fir.result %a_upd : !fir.array<?xf32>
    }
    fir.array_merge_store %a_arr, %result to %arg0
        : !fir.array<?xf32>, !fir.array<?xf32>, !fir.ref<!fir.array<?xf32>>
    return
  }
}

// With -fopenmp flag the loop becomes:
// omp.parallel {
//   omp.wsloop for (%iv : index = %c1 to %n_idx step %c1) {
//     ... body ...
//     omp.yield
//   }
//   omp.terminator
// }

hlfir.content:
// *** IR Dump After HLFIR Lowering ***
module @_QMdo_concurrent_scale {
  func.func @_QPdo_concurrent_scale(
      %arg0: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "a", fir.inout},
      %arg1: !fir.ref<!fir.array<?xf32>> {fir.bindc_name = "b", fir.in},
      %arg2: !fir.ref<f32>               {fir.bindc_name = "scale", fir.in},
      %arg3: !fir.ref<i32>               {fir.bindc_name = "n", fir.in}
  ) {
    %0 = fir.load %arg3 : !fir.ref<i32>
    %1 = fir.convert %0 : (i32) -> index
    %shape = fir.shape %1 : (index) -> !fir.shape<1>

    %a:2 = hlfir.declare %arg0(%shape)
        {fortran_attrs = #fir.var_attrs<intent_out>, uniq_name = "_QFdo_concurrent_scaleEa"}
        : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> (!fir.box<!fir.array<?xf32>>, !fir.ref<!fir.array<?xf32>>)

    %b:2 = hlfir.declare %arg1(%shape)
        {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFdo_concurrent_scaleEb"}
        : (!fir.ref<!fir.array<?xf32>>, !fir.shape<1>) -> (!fir.box<!fir.array<?xf32>>, !fir.ref<!fir.array<?xf32>>)

    %scale:2 = hlfir.declare %arg2
        {fortran_attrs = #fir.var_attrs<intent_in>, uniq_name = "_QFdo_concurrent_scaleEscale"}
        : (!fir.ref<f32>) -> (!fir.ref<f32>, !fir.ref<f32>)

    // DO CONCURRENT represented as hlfir.elemental with 'unordered'
    // This preserves the independence guarantee through all HLFIR passes
    %expr = hlfir.elemental %shape unordered
        : (!fir.shape<1>) -> !hlfir.expr<?xf32> {
    ^bb0(%i: index):
      %b_el    = hlfir.apply %b#0, %i : (!fir.box<!fir.array<?xf32>>, index) -> f32
      %sc_val  = fir.load %scale#0 : !fir.ref<f32>
      %product = arith.mulf %b_el, %sc_val fastmath<contract> : f32
      hlfir.yield_element %product : f32
    }
    hlfir.assign %expr to %a#0 : !hlfir.expr<?xf32>, !fir.box<!fir.array<?xf32>>
    hlfir.destroy %expr : !hlfir.expr<?xf32>
    return
  }
}
